// Extract source name from feed
const item = $input.item.json;

let sourceName = 'Unknown';
if (item.link?.includes('justice.gov')) sourceName = 'DOJ';
else if (item.link?.includes('fbi.gov')) sourceName = 'FBI';
else if (item.link?.includes('sec.gov')) sourceName = 'SEC';
else if (item.link?.includes('ftc.gov')) sourceName = 'FTC';

// Extract state from title/content
const text = (item.title + ' ' + (item.contentSnippet || '')).toLowerCase();
let state = null;

const statePatterns = {
  'minnesota': 'MN', 'mn ': 'MN',
  'california': 'CA', 'ca ': 'CA',
  'texas': 'TX', 'tx ': 'TX',
  'new york': 'NY', 'ny ': 'NY',
  'florida': 'FL', 'fl ': 'FL',
  'illinois': 'IL', 'chicago': 'IL',
  'pennsylvania': 'PA', 'philadelphia': 'PA',
  'ohio': 'OH',
  'georgia': 'GA', 'atlanta': 'GA',
  'north carolina': 'NC'
};

for (const [pattern, code] of Object.entries(statePatterns)) {
  if (text.includes(pattern)) {
    state = code;
    break;
  }
}

// Detect fraud type
let fraudType = 'other';
if (text.includes('healthcare') || text.includes('medicare') || text.includes('medicaid')) fraudType = 'healthcare';
else if (text.includes('securities') || text.includes('investment') || text.includes('ponzi') || text.includes('stock')) fraudType = 'securities';
else if (text.includes('tax') || text.includes('irs')) fraudType = 'tax';
else if (text.includes('wire fraud') || text.includes('mail fraud')) fraudType = 'wire';
else if (text.includes('corruption') || text.includes('bribery') || text.includes('public official')) fraudType = 'corruption';
else if (text.includes('government') || text.includes('contract') || text.includes('federal')) fraudType = 'government';
else if (text.includes('welfare') || text.includes('benefits') || text.includes('snap') || text.includes('unemployment')) fraudType = 'welfare';
else if (text.includes('insurance')) fraudType = 'insurance';
else if (text.includes('bank') || text.includes('financial') || text.includes('loan')) fraudType = 'financial';

// Calculate importance score
let importance = 50;

// Boost for dollar amounts
const amounts = text.match(/\$[\d,]+(?:\.\d{2})?(?:\s*(?:million|billion|thousand))?/gi) || [];
if (amounts.length > 0) {
  const maxAmount = amounts.reduce((max, amt) => {
    let value = parseFloat(amt.replace(/[$,]/g, ''));
    if (amt.toLowerCase().includes('billion')) value *= 1000000000;
    else if (amt.toLowerCase().includes('million')) value *= 1000000;
    else if (amt.toLowerCase().includes('thousand')) value *= 1000;
    return Math.max(max, value);
  }, 0);

  if (maxAmount > 1000000000) importance += 30;
  else if (maxAmount > 100000000) importance += 25;
  else if (maxAmount > 10000000) importance += 20;
  else if (maxAmount > 1000000) importance += 15;
  else if (maxAmount > 100000) importance += 10;
}

// Boost for priority states
if (state === 'MN' || state === 'CA') importance += 15;

// Boost for federal sources
if (sourceName === 'DOJ' || sourceName === 'FBI') importance += 10;

// Boost for sentencing/conviction (more newsworthy)
if (text.includes('sentenced') || text.includes('convicted') || text.includes('pleaded guilty')) importance += 5;

importance = Math.min(importance, 100);

return {
  title: item.title,
  source_url: item.link,
  source_name: sourceName,
  published_at: item.pubDate || item.isoDate || new Date().toISOString(),
  summary: item.contentSnippet || item.description || null,
  fraud_type: fraudType,
  state: state,
  importance_score: importance,
  entities: {
    dollar_amounts: amounts
  }
};

